**src/App.jsx**
```jsx
import { useEffect, useState } from 'react';

const STORAGE_KEY = 'todos';
const FILTERS = ['all', 'active', 'completed'];

function loadTodos() {
  try { return JSON.parse(localStorage.getItem(STORAGE_KEY)) ?? []; }
  catch { return []; }
}

export default function App() {
  const [todos, setTodos] = useState(loadTodos);
  const [text, setText] = useState('');
  const [filter, setFilter] = useState('all');
  const [editingId, setEditingId] = useState(null);
  const [editText, setEditText] = useState('');

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }, [todos]);

  const addTodo = (e) => {
    e.preventDefault();
    const title = text.trim();
    if (!title) return;
    setTodos([...todos, { id: crypto.randomUUID(), title, done: false }]);
    setText('');
  };
  const toggleTodo = (id) =>
    setTodos(todos.map((t) => (t.id === id ? { ...t, done: !t.done } : t)));
  const deleteTodo = (id) => setTodos(todos.filter((t) => t.id !== id));
  const startEdit = (todo) => { setEditingId(todo.id); setEditText(todo.title); };
  const saveEdit = () => {
    const title = editText.trim();
    if (title) setTodos(todos.map((t) => (t.id === editingId ? { ...t, title } : t)));
    else deleteTodo(editingId);
    setEditingId(null);
  };
  const clearCompleted = () => setTodos(todos.filter((t) => !t.done));

  const remaining = todos.filter((t) => !t.done).length;
  const visible = todos.filter((t) =>
    filter === 'all' ? true : filter === 'active' ? !t.done : t.done
  );

  return (
    <main className="app">
      <h1>Todo List</h1>
      <form onSubmit={addTodo} className="add-form">
        <input value={text} onChange={(e) => setText(e.target.value)}
          placeholder="What needs to be done?" aria-label="New todo" autoFocus />
        <button type="submit">Add</button>
      </form>

      <div className="filters">
        {FILTERS.map((f) => (
          <button key={f} className={f === filter ? 'active' : ''}
            onClick={() => setFilter(f)}>{f}</button>
        ))}
      </div>

      <ul className="todo-list">
        {visible.map((todo) => (
          <li key={todo.id} className={todo.done ? 'done' : ''}>
            <input type="checkbox" checked={todo.done}
              onChange={() => toggleTodo(todo.id)}
              aria-label={`Mark "${todo.title}" as done`} />
            {editingId === todo.id ? (
              <input className="edit" value={editText} autoFocus
                onChange={(e) => setEditText(e.target.value)}
                onBlur={saveEdit}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') saveEdit();
                  if (e.key === 'Escape') setEditingId(null);
                }} />
            ) : (
              <span onDoubleClick={() => startEdit(todo)}>{todo.title}</span>
            )}
            <button className="delete" onClick={() => deleteTodo(todo.id)}
              aria-label={`Delete "${todo.title}"`}>×</button>
          </li>
        ))}
      </ul>

      {todos.length > 0 && (
        <footer>
          <span>{remaining} item{remaining === 1 ? '' : 's'} left</span>
          <button onClick={clearCompleted} disabled={remaining === todos.length}>
            Clear completed
          </button>
        </footer>
      )}
      <p className="hint">Double-click a todo to edit it.</p>
    </main>
  );
}
```

